<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {RouterLink} from 'vue-router'
import {api} from '../../api'
import {loadAMap,type AMapSDK,type MapInstance,type MarkerInstance,type MapEvent,type MapRuntime} from './amap-runtime'
export interface LocationItem {name:string;address:string;city?:string;latitude:number;longitude:number}
const props=defineProps<{city:string;latitude:number|null;longitude:number|null;contextKey:string;disabled:boolean;entityLabel?:string}>()
const emit=defineEmits<{select:[item:LocationItem]}>()
const container=ref<HTMLElement>(),query=ref(''),items=ref<LocationItem[]>([]),draft=ref<LocationItem|null>(null)
const loading=ref(false),searching=ref(false),resolving=ref(false),error=ref(''),mapError=ref(''),ready=ref(false)
let map:MapInstance|undefined,marker:MarkerInstance|undefined,sdk:AMapSDK|undefined,generation=0,operation=0,alive=true
function valid(item:LocationItem){return Number.isFinite(item.latitude)&&Number.isFinite(item.longitude)&&Math.abs(item.latitude)<=90&&Math.abs(item.longitude)<=180&&!!item.address}
function destroy(){map?.destroy();map=undefined;marker=undefined;sdk=undefined;ready.value=false}
function reset(){generation++;operation++;destroy();query.value='';items.value=[];draft.value=null;error.value='';searching.value=false;resolving.value=false}
function putMarker(item:Pick<LocationItem,'latitude'|'longitude'>){if(!map||!sdk)return;const point=[item.longitude,item.latitude];if(marker)marker.setPosition(point);else{marker=new sdk.Marker({position:point,draggable:!props.disabled});marker.setMap(map);marker.on('dragend',reverse)}map.setCenter(point)}
async function init(){const current=++generation;destroy();loading.value=true;mapError.value='';try{const config=await api<MapRuntime>('/stores/map-runtime');if(!alive||current!==generation)return;const result=await loadAMap(config);if(!alive||current!==generation||!container.value)return;sdk=result;map=new sdk.Map(container.value,{zoom:16,resizeEnable:true});map.on('click',reverse);ready.value=true;if(props.latitude!==null&&props.longitude!==null)putMarker({latitude:props.latitude,longitude:props.longitude});else if(props.city)map.setCity?.(props.city)}catch{if(alive&&current===generation)mapError.value='地图未能加载。请检查高德配置或网络后重试；原位置会保留。'}finally{if(current===generation)loading.value=false}}
async function search(){if(props.disabled||searching.value||!query.value.trim())return;const current=++operation,page=generation;searching.value=true;error.value='';items.value=[];draft.value=null;try{const data=await api<{items:LocationItem[]}>(`/stores/map-search?${new URLSearchParams({q:query.value.trim(),city:props.city})}`);if(!alive||page!==generation||current!==operation)return;items.value=data.items.filter(valid);if(!items.value.length)error.value='未找到位置，请换一个关键词。'}catch(e){if(current===operation&&page===generation)error.value=e instanceof Error?e.message:'位置查询失败，请重试。'}finally{if(current===operation&&page===generation)searching.value=false}}
function choose(item:LocationItem){operation++;resolving.value=false;draft.value={...item};error.value='';putMarker(item)}
async function reverse(event:MapEvent){if(props.disabled)return;const point=event.lnglat||event.target?.getPosition();if(!point)return;const latitude=point.getLat(),longitude=point.getLng();if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)return;const current=++operation,page=generation;draft.value=null;items.value=[];resolving.value=true;error.value='';putMarker({latitude,longitude});try{const item=await api<LocationItem>(`/stores/map-reverse?${new URLSearchParams({latitude:String(latitude),longitude:String(longitude)})}`);if(!alive||current!==operation||page!==generation)return;if(!valid(item))throw new Error('未识别该位置，请搜索附近地点。');draft.value={...item}}catch(e){if(current===operation&&page===generation)error.value=e instanceof Error?e.message:'位置解析失败，请重选。'}finally{if(current===operation&&page===generation)resolving.value=false}}
function apply(){if(draft.value&&!props.disabled&&!resolving.value)emit('select',{...draft.value})}
watch(query,()=>{operation++;draft.value=null;items.value=[];searching.value=false;resolving.value=false})
watch(()=>props.contextKey,()=>{reset();init()})
watch(()=>props.disabled,()=>{operation++;draft.value=null;items.value=[];searching.value=false;resolving.value=false})
watch(()=>[props.latitude,props.longitude],()=>{if(props.latitude!==null&&props.longitude!==null)putMarker({latitude:props.latitude,longitude:props.longitude});else{marker?.setMap(null);marker=undefined}draft.value=null})
onMounted(init);onBeforeUnmount(()=>{alive=false;reset()})
</script>
<template><section class="location-picker" aria-label="高德地图定位"><h3>地图定位</h3><div class="map-search"><input v-model="query" type="search" maxlength="100" :aria-label="`搜索${entityLabel||'前置仓'}位置`" placeholder="搜索小区、楼宇或详细地址" :disabled="disabled" @keydown.enter.prevent="search"><button type="button" class="secondary-button" data-test="search" :disabled="disabled||searching||!query.trim()" @click="search">{{searching?'查询中…':'搜索地图'}}</button></div><p class="help-text">搜索地点后选择结果，或点击地图、拖动标记微调；确认后同步地址和坐标。</p><p v-if="loading" role="status">地图加载中…</p><div ref="container" class="map-canvas" :aria-label="`${entityLabel||'前置仓'}定位地图`" :aria-busy="loading"></div><p v-if="mapError" role="alert">{{mapError}} <button type="button" class="text-button" :disabled="loading" @click="init">重新加载地图</button><RouterLink to="/stores/map-settings">检查地图配置</RouterLink></p><ul v-if="items.length" class="map-results"><li v-for="(item,index) in items" :key="index"><button type="button" data-test="map-result" :disabled="disabled" @click="choose(item)"><strong>{{item.name}}</strong><span>{{item.address}}</span></button></li></ul><p v-if="error" role="alert">{{error}}</p><p v-if="resolving" role="status">正在识别地图位置…</p><div v-if="draft" class="location-draft"><div><strong>{{draft.name||'已选位置'}}</strong><p>{{draft.address}}</p><small>经度 {{draft.longitude}} · 纬度 {{draft.latitude}}</small></div><button type="button" data-test="apply-location" class="primary-button" :disabled="disabled||resolving" @click="apply">使用此位置</button></div></section></template>
<style scoped>
.location-picker h3{font-size:16px;margin:0 0 12px}.map-search{display:flex;gap:12px}.map-search input{flex:1;min-width:0}.map-canvas{height:360px;width:100%;background:var(--mall-color-background,#f4f5f7);border:1px solid var(--mall-color-border);border-radius:8px}.map-results{list-style:none;padding:0;max-height:240px;overflow:auto}.map-results button{display:flex;flex-direction:column;gap:6px;background:white;border:0;border-bottom:1px solid var(--mall-color-border);padding:12px;width:100%;text-align:left}.location-draft{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px;background:var(--mall-color-brand-soft);margin-top:12px;border-radius:8px}.location-draft p{margin:8px 0}.location-draft small{color:var(--mall-color-muted)}@media(max-width:600px){.map-search,.location-draft{flex-direction:column;align-items:stretch}.map-canvas{height:300px}}
</style>
